1	/**
2	 * Test filtering module for the eval command.
3	 *
4	 * This module provides functions to filter test cases based on previous evaluation results.
5	 * The filtering functions are named to match their corresponding CLI flags:
6	 *
7	 * - `--filter-failing` -> `filterFailingTests`: Returns all non-passing tests (failures + errors)
8	 * - `--filter-failing-only` -> `filterFailingOnlyTests`: Returns only assertion failures (excludes errors)
9	 * - `--filter-errors-only` -> `filterErrorTests`: Returns only tests that resulted in errors
10	 *
11	 * Runtime variables (like `_conversation`, `sessionId`) are automatically filtered out when
12	 * matching test cases to results, ensuring proper matching even when multi-turn strategies
13	 * add runtime state to test vars.
14	 *
15	 * @module commands/eval/filterTests
16	 */
17	
18	import logger from '../../logger';
19	import { ResultFailureReason } from '../../types/index';
20	import { getTestCaseDeduplicationKey } from '../../util/comparison';
21	import { filterByRange } from '../../util/filterRange';
22	import { warnEmptyFilterRange } from '../../util/filterRangeWarn';
23	import { filterTestsByResults } from './filterTestsUtil';
24	
25	import type { TestSuite } from '../../types/index';
26	
27	/**
28	 * Logs a warning when a filter returns no tests.
29	 * @param filterType - The CLI flag name (e.g., 'filter-failing')
30	 * @param pathOrId - The path or eval ID that was filtered
31	 * @param reason - Description of what the filter was looking for (e.g., 'no failures/errors')
32	 */
33	function logNoTestsWarning(filterType: string, pathOrId: string, reason: string): void {
34	  logger.warn(
35	    `--${filterType} returned no tests. The evaluation "${pathOrId}" may have ${reason}, ` +
36	      'or the test suite may have changed since the evaluation was run.',
37	  );
38	}
39	
40	/**
41	 * Options for filtering test cases in a test suite.
42	 */
43	export interface FilterOptions {
44	  /** Path or ID to filter tests that resulted in errors */
45	  errorsOnly?: string;
46	  /** Path or ID to filter tests that did not pass (failed from assert or errors) */
47	  failing?: string;
48	  /** Path or ID to filter tests that failed assertions only (excludes errors) */
49	  failingOnly?: string;
50	  /** Number of tests to take from the beginning */
51	  firstN?: number | string;
52	  /** Key-value pair(s) (format: "key=value") to filter tests by metadata. Multiple values use AND logic. */
53	  metadata?: string | string[];
54	  /** Regular expression pattern to filter tests by description */
55	  pattern?: string;
56	  /** Zero-based test index range in start:end format. End is exclusive. */
57	  range?: string;
58	  /** Number of random tests to sample */
59	  sample?: number | string;
60	}
61	
62	type Tests = NonNullable<TestSuite['tests']>;
63	
64	/**
65	 * Filters a test suite to only include all tests that did not pass (failures + errors)
66	 * @param testSuite - The test suite containing all tests
67	 * @param pathOrId - Either a file path to a JSON results file or an eval ID
68	 * @returns A filtered array of tests that failed in the specified eval
69	 */
70	async function filterFailingTests(testSuite: TestSuite, pathOrId: string): Promise<Tests> {
71	  // Filter for all non-successful results (both assertion failures and errors)
72	  return filterTestsByResults(testSuite, pathOrId, (result) => !result.success);
73	}
74	
75	/**
76	 * Filters a test suite to only include tests that failed assertions (excludes errors)
77	 * @param testSuite - The test suite containing all tests
78	 * @param pathOrId - Either a file path to a JSON results file or an eval ID
79	 * @returns A filtered array of tests that failed assertions (not errors) in the specified eval
80	 */
81	async function filterFailingOnlyTests(testSuite: TestSuite, pathOrId: string): Promise<Tests> {
82	  // Filter for assertion failures only, excluding errors
83	  return filterTestsByResults(
84	    testSuite,
85	    pathOrId,
86	    (result) => !result.success && result.failureReason !== ResultFailureReason.ERROR,
87	  );
88	}
89	
90	/**
91	 * Filters a test suite to only include tests that resulted in errors from a specific eval
92	 * @param testSuite - The test suite containing all tests
93	 * @param pathOrId - Either a file path to a JSON results file or an eval ID
94	 * @returns A filtered array of tests that resulted in errors in the specified evaluation
95	 */
96	async function filterErrorTests(testSuite: TestSuite, pathOrId: string): Promise<Tests> {
97	  return filterTestsByResults(
98	    testSuite,
99	    pathOrId,
100	    (result) => result.failureReason === ResultFailureReason.ERROR,
101	  );
102	}
103	
104	/**
105	 * Applies multiple filters to a test suite based on the provided options.
106	 * Filters are applied in the following order:
107	 * 1. Metadata filter
108	 * 2. Failing tests filter
109	 * 3. Error tests filter
110	 * 4. Pattern filter
111	 * 5. Range filter
112	 * 6. First N filter
113	 * 7. Random sample filter
114	 *
115	 * @param testSuite - The test suite containing all tests
116	 * @param options - Configuration options for filtering
117	 * @returns A filtered array of tests that match all the specified criteria
118	 * @throws {Error} If metadata filter format is invalid or if numeric filters contain non-numeric values
119	 */
120	export async function filterTests(testSuite: TestSuite, options: FilterOptions): Promise<Tests> {
121	  let tests = testSuite.tests || [];
122	
123	  logger.debug(`Starting filterTests with options: ${JSON.stringify(options)}`);
124	  logger.debug(`Initial test count: ${tests.length}`);
125	
126	  if (Object.keys(options).length === 0) {
127	    logger.debug('No filter options provided, returning all tests');
128	    return tests;
129	  }
130	
131	  if (options.metadata) {
132	    // Normalize to array for consistent handling
133	    const metadataFilters = Array.isArray(options.metadata) ? options.metadata : [options.metadata];
134	
135	    // Validate all filters first
136	    const parsedFilters: Array<{ key: string; value: string }> = [];
137	    for (const filter of metadataFilters) {
138	      const [key, ...valueParts] = filter.split('=');
139	      const value = valueParts.join('='); // Rejoin in case value contains '='
140	      if (!key || value === undefined || value === '') {
141	        throw new Error('--filter-metadata must be specified in key=value format');
142	      }
143	      parsedFilters.push({ key, value });
144	    }
145	
146	    logger.debug(
147	      `Filtering for metadata conditions (AND logic): ${parsedFilters.map((f) => `${f.key}=${f.value}`).join(', ')}`,
148	    );
149	    logger.debug(`Before metadata filter: ${tests.length} tests`);
150	
151	    tests = tests.filter((test) => {
152	      if (!test.metadata) {
153	        logger.debug(`Test has no metadata: ${test.description || 'unnamed test'}`);
154	        return false;
155	      }
156	
157	      // ALL conditions must match (AND logic)
158	      for (const { key, value } of parsedFilters) {
159	        const testValue = test.metadata[key];
160	        let matches = false;
161	
162	        if (Array.isArray(testValue)) {
163	          // For array metadata, check if any value includes the search term
164	          matches = testValue.some((v) => v.toString().includes(value));
165	        } else if (testValue !== undefined) {
166	          // For single value metadata, check if it includes the search term
167	          matches = testValue.toString().includes(value);
168	        }
169	
170	        if (!matches) {
171	          logger.debug(
172	            `Test "${test.description || 'unnamed test'}" metadata doesn't match. Expected ${key} to include ${value}, got ${JSON.stringify(test.metadata)}`,
173	          );
174	          return false;
175	        }
176	      }
177	
178	      return true;
179	    });
180	
181	    logger.debug(`After metadata filter: ${tests.length} tests remain`);
182	  }
183	
